cssReset:
/*Css Reset Start*/
body, #body_style { width: 100% !important; background: #ffffff; font-family: Arial; color: #ffffff; line-height: 1; }
.ExternalClass { width: 100%; }
.ExternalClass, .ExternalClass p, .ExternalClass span, .ExternalClass font, .ExternalClass td, .ExternalClass table, .ExternalClass div { line-height: 100%; }
body { -webkit-text-size-adjust: none; -ms-text-size-adjust: none; margin: 0 !important; }
body, img, div, p, ul, li, span, strong, a { margin: 0; padding: 0; }
table { border-spacing: 0; }
table td, table th { border-collapse: collapse; }
div { margin: 0 !important; padding: 0 !important; }
a { outline: none !important; }
a[href^="tel"], a[href^="sms"] { text-decoration: none; color: inherit !important; }
img { display: block !important; border: none !important; outline: none !important; text-decoration: none; }
table { border-collapse: collapse; mso-table-lspace: 0pt; mso-table-rspace: 0pt; }
.appleLinks { color: inherit; text-decoration: none; }
.appleLinks a { color: inherit; text-decoration: none; }
/*media query Start*/
@media only screen and (max-width: 699px) {
  td[class="Wrapper"] table[class="Container"] { width: 100% !important; }
  td[class="Wrapper"] .hero_image img { width: 100% !important; height: auto !important; }
  .hideSpace { display: none !important; }
  .blockSpace { width: 100% !important; height: auto !important; display: block !important; }
  *[class="gmail-fix"] { display: none !important; }
  td[class="Wrapper"] .col-100 { width: 100% !important; height: auto !important; display: block !important; float: none !important; }
  td[class="Wrapper"] .col-50 { width: 50% !important; height: auto !important; float: none !important; }
  .brk_none br { display: none !important; }
  td[class="Wrapper"] .fragment_image img { width: 100% !important; height: auto !important; }
}
@media only screen and (max-width: 479px) {
  .setPadding { padding-left: 20px !important; padding-right: 20px !important; }
  .blockSpace1 { width: 100% !important; height: 20px !important; display: block !important; }
  td[class="Wrapper"] .col-50 { width: 100% !important; height: auto !important; display: block !important; }
  td[class="Wrapper"] .col-header { width: 100% !important; float: none !important; display: block !important; }
  table[class="dec_width"] { width: 280px !important; }
  img[class="rezize"] { width: 100% !important; height: auto !important; }
  .button_size { width: 100%; }
}
